"use client";

import { useState, useEffect } from 'react';
import { useSDGStore } from '@/services/storage/sdg-store';
import { CodeEditor } from '@/components/student/CodeEditor';
import { 
  Lock, 
  Unlock, 
  CheckCircle2, 
  Play, 
  Globe, 
  Sparkles,
  ChevronRight,
  TrendingDown,
  Wind
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { mergeModuleCode } from '@/lib/merge';

export default function StudentLab() {
  const { currentRoadmap, studentProgress, updateProgress, unlockNextModule } = useSDGStore();
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [localCode, setLocalCode] = useState('');
  const [isVerifying, setIsVerifying] = useState(false);
  const [showMerge, setShowMerge] = useState(false);

  // Initialize first module
  useEffect(() => {
    if (currentRoadmap && currentRoadmap.modules.length > 0 && !activeModuleId) {
      setActiveModuleId(currentRoadmap.modules[0].id);
      setLocalCode(currentRoadmap.modules[0].codeTemplate);
    }
  }, [currentRoadmap, activeModuleId]);

  if (!currentRoadmap) return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center">
       <div className="text-center space-y-4">
          <Globe className="w-12 h-12 text-slate-800 mx-auto animate-pulse" />
          <p className="text-[10px] font-black uppercase tracking-widest text-slate-700">Waiting for Teacher Architect...</p>
       </div>
    </div>
  );

  const activeModule = currentRoadmap.modules.find(m => m.id === activeModuleId);
  const activeProgress = studentProgress.find(p => p.moduleId === activeModuleId);

  const handleVerify = async () => {
    if (!activeModule) return;
    setIsVerifying(true);
    
    // Simulate verification (using regex check for now as per Snap Logic spec)
    setTimeout(() => {
      const passed = localCode.includes(activeModule.testCriteria.replace("contains('", "").replace("')", ""));
      if (passed) {
        updateProgress(activeModule.id, 'COMPLETED', localCode);
        unlockNextModule(activeModule.id);
      }
      setIsVerifying(false);
    }, 1500);
  };

  return (
    <div className="h-screen bg-slate-950 flex overflow-hidden font-sans selection:bg-emerald-500/30 text-slate-100">
      
      {/* Sidebar Progress */}
      <aside className="w-80 border-r border-white/5 bg-slate-950/50 flex flex-col">
        <div className="p-8 border-b border-white/5">
           <div className="flex items-center space-x-3 mb-6">
              <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center">
                <Globe className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-[10px] font-black uppercase tracking-tighter italic">Sustain-Ability Lab</h1>
           </div>
           <div className="space-y-1">
              <span className="text-[9px] font-black uppercase text-emerald-500 tracking-widest">Active Project</span>
              <h2 className="text-xl font-black uppercase italic tracking-tighter truncate">{currentRoadmap.courseTitle}</h2>
           </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {currentRoadmap.modules.map((mod, idx) => {
            const progress = studentProgress.find(p => p.moduleId === mod.id);
            const status = progress?.status || 'LOCKED';
            const isActive = activeModuleId === mod.id;

            return (
              <button
                key={mod.id}
                disabled={status === 'LOCKED'}
                onClick={() => {
                  setActiveModuleId(mod.id);
                  setLocalCode(progress?.savedCode || mod.codeTemplate);
                }}
                className={`w-full p-4 rounded-2xl border transition-all text-left flex items-start space-x-4 ${
                  isActive ? 'bg-emerald-600/10 border-emerald-500/30 shadow-lg shadow-emerald-500/5' : 
                  status === 'LOCKED' ? 'bg-transparent border-white/5 opacity-40 cursor-not-allowed' :
                  status === 'COMPLETED' ? 'bg-slate-900 border-white/10 hover:border-emerald-500/50' :
                  'bg-slate-900 border-white/5 hover:border-white/20'
                }`}
              >
                <div className="shrink-0 mt-1">
                  {status === 'COMPLETED' ? <CheckCircle2 className="w-4 h-4 text-emerald-500" /> : 
                   status === 'LOCKED' ? <Lock className="w-4 h-4 text-slate-700" /> : 
                   <Unlock className="w-4 h-4 text-slate-300" />}
                </div>
                <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase tracking-widest text-slate-500">Module 0{idx + 1}</p>
                  <p className={`text-xs font-black uppercase italic tracking-tighter ${isActive ? 'text-emerald-500' : 'text-slate-200'}`}>{mod.title}</p>
                </div>
              </button>
            );
          })}
        </div>

        <div className="p-8 border-t border-white/5 bg-slate-950">
           <button 
             onClick={() => setShowMerge(true)}
             className="w-full h-12 bg-white text-slate-950 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-slate-200 transition-all flex items-center justify-center space-x-3"
           >
              <span>Final Merge Preview</span>
              <Sparkles className="w-4 h-4" />
           </button>
        </div>
      </aside>

      {/* Main Sandbox */}
      <main className="flex-1 flex flex-col p-8 lg:p-12 space-y-8 overflow-hidden">
        
        {/* Module Header */}
        {activeModule && (
          <header className="flex items-center justify-between">
            <div className="space-y-2">
              <div className="flex items-center space-x-3 text-[10px] font-black uppercase tracking-widest text-emerald-500">
                <ChevronRight className="w-4 h-4" />
                <span>Current Objective: {activeModule.title}</span>
              </div>
              <h3 className="text-3xl font-black uppercase italic tracking-tighter text-white max-w-2xl">{activeModule.description}</h3>
            </div>
            
            <button 
              onClick={handleVerify}
              disabled={isVerifying || activeProgress?.status === 'COMPLETED'}
              className="h-14 bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-900 text-white rounded-[1.5rem] px-12 font-black text-[10px] uppercase tracking-widest transition-all flex items-center space-x-4 shadow-xl shadow-emerald-500/20"
            >
              {isVerifying ? (
                <>
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  <span>Verifying...</span>
                </>
              ) : activeProgress?.status === 'COMPLETED' ? (
                <>
                  <CheckCircle2 className="w-4 h-4" />
                  <span>Module Passed</span>
                </>
              ) : (
                <>
                  <Play className="w-4 h-4" />
                  <span>Verify Logic</span>
                </>
              )}
            </button>
          </header>
        )}

        <div className="flex-1 flex space-x-8 min-h-0">
          {/* Editor Section */}
          <div className="flex-[3] min-h-0">
            <CodeEditor 
              code={localCode} 
              onChange={(val) => setLocalCode(val || '')} 
              language="python"
            />
          </div>

          {/* Digital Twin Section */}
          <div className="flex-[2] flex flex-col space-y-8 min-h-0">
             <div className="flex-1 bg-slate-900/50 rounded-[2.5rem] border border-white/5 relative overflow-hidden flex flex-col items-center justify-center p-12">
                <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_120%,rgba(16,185,129,0.1),transparent)]" />
                
                {/* Visual Feedback: Digital Twin */}
                <div className="relative z-10 text-center space-y-8">
                   <motion.div 
                     animate={{ 
                       y: [0, -10, 0],
                       opacity: [0.5, 1, 0.5]
                     }}
                     transition={{ duration: 4, repeat: Infinity }}
                     className="w-32 h-32 mx-auto bg-emerald-500/10 rounded-full flex items-center justify-center relative shadow-[0_0_50px_rgba(16,185,129,0.15)]"
                   >
                      <Globe className="w-16 h-16 text-emerald-500" />
                   </motion.div>

                   <div className="space-y-4">
                      <div className="flex items-center justify-center space-x-3">
                         <Wind className="w-4 h-4 text-slate-500" />
                         <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">Emission Levels</span>
                      </div>
                      <div className="h-2 w-48 bg-slate-800 rounded-full mx-auto overflow-hidden">
                         <motion.div 
                           initial={{ width: "80%" }}
                           animate={{ width: activeProgress?.status === 'COMPLETED' ? "30%" : "80%" }}
                           className="h-full bg-emerald-500"
                         />
                      </div>
                      <div className="flex items-center justify-center space-x-2 text-emerald-500">
                         <TrendingDown className="w-4 h-4" />
                         <span className="text-xl font-black italic tracking-tighter">-52% Optimized</span>
                      </div>
                   </div>
                </div>
             </div>

             <div className="h-1/3 bg-slate-900 border border-white/5 rounded-[2.5rem] p-8 space-y-6">
                <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-500">Modular Challenge Context</h4>
                <div className="space-y-4">
                   <p className="text-xs font-bold text-slate-300 leading-relaxed italic border-l-2 border-emerald-500/30 pl-4">
                     {activeModule?.task}
                   </p>
                </div>
             </div>
          </div>
        </div>
      </main>

      {/* Final Merge Modal */}
      <AnimatePresence>
        {showMerge && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] bg-slate-950/90 backdrop-blur-xl flex items-center justify-center p-8 lg:p-24"
          >
            <motion.div 
              initial={{ scale: 0.9, y: 20 }}
              animate={{ scale: 1, y: 0 }}
              className="w-full h-full max-w-6xl bg-slate-900 border border-white/10 rounded-[3rem] shadow-2xl overflow-hidden flex flex-col"
            >
              <div className="h-20 border-b border-white/5 px-12 flex items-center justify-between shrink-0">
                <div className="space-y-1">
                  <h3 className="text-xl font-black uppercase italic tracking-tighter">SDG Project: Final Merge</h3>
                  <p className="text-[10px] font-black uppercase tracking-widest text-emerald-500">Consolidated Code Artifact</p>
                </div>
                <button 
                  onClick={() => setShowMerge(false)}
                  className="w-10 h-10 rounded-full bg-slate-950 border border-white/5 flex items-center justify-center hover:bg-white hover:text-slate-950 transition-all"
                >
                  <Sparkles className="w-4 h-4" />
                </button>
              </div>
              <div className="flex-1 p-12 overflow-y-auto">
                <pre className="text-xs font-mono text-slate-400 bg-slate-950/50 p-8 rounded-3xl border border-white/5 leading-relaxed selection:bg-emerald-500/30">
                  {mergeModuleCode(currentRoadmap, studentProgress)}
                </pre>
              </div>
              <div className="h-20 border-t border-white/5 px-12 flex items-center justify-end space-x-6 shrink-0 bg-slate-950/50">
                <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">Ready for SDG Impact Verification</span>
                <button 
                  disabled
                  className="px-8 h-10 bg-emerald-600/20 text-emerald-500 border border-emerald-500/30 rounded-full font-black text-[9px] uppercase tracking-widest cursor-not-allowed"
                >
                  Deploy to Digital Twin
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
